package main

import (
	"fmt"
	"regexp"
	"sort"
	"strings"
)

// The ADMX format's fixed parts (Microsoft's ADMX schema, MS-GPREG § 7, and its examples in
// § 4.4, read 2026-11-18): the one namespace every ADMX and ADML file declares, and schema 1.0.
const (
	gpNamespace   = "http://schemas.microsoft.com/GroupPolicy/2006/07/PolicyDefinitions"
	schemaVersion = "1.0"
	header        = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by scripts/group-policy from apps/desktop/src-tauri/src/managed_policy/policies.json. Don't edit it here: change policies.json and run ./scripts/group-policy.sh. -->
`
)

type file struct {
	path    string // relative to the output dir
	content []byte
}

// The names one template derives from its definition. The vendor's namespace is what a second
// product's template reuses through `<using>`, and the product's sits under it (the
// `Mozilla.Policies` / `Mozilla.Policies.Firefox` shape); both start with `namespaceVendor`, the
// vendor's full name. The prefixes and filenames are the lowercased category names.
type names struct {
	vendorNS, productNS         string
	vendorPrefix, productPrefix string
	supportedOn                 string
}

func namesOf(gp groupPolicy) names {
	vendorNS := gp.NamespaceVendor + ".Policies"
	return names{
		vendorNS:      vendorNS,
		productNS:     vendorNS + "." + gp.ProductCategory,
		vendorPrefix:  strings.ToLower(gp.VendorCategory),
		productPrefix: strings.ToLower(gp.ProductCategory),
		supportedOn:   "SUPPORTED_" + gp.ProductCategory + "_Windows",
	}
}

// generate builds the four template files: the vendor's ADMX and ADML (the shared vendor
// category) and the product's, which hangs its category and policies under it.
func generate(def definition) ([]file, error) {
	gp := def.GroupPolicy
	n := namesOf(gp)

	files := []file{
		{n.vendorPrefix + ".admx", []byte(vendorADMX(def, n))},
		{"en-US/" + n.vendorPrefix + ".adml", []byte(adml(gp.Revision, gp.VendorCategory, "Group Policy categories for "+gp.VendorCategory+" products.",
			[][2]string{{gp.VendorCategory, gp.VendorCategory}}, nil))},
		{n.productPrefix + ".admx", []byte(productADMX(def, n))},
		{"en-US/" + n.productPrefix + ".adml", []byte(productADML(def, n))},
	}
	for _, pair := range [][2]int{{0, 1}, {2, 3}} {
		if err := checkReferences(files[pair[0]], files[pair[1]]); err != nil {
			return nil, err
		}
	}
	return files, nil
}

func vendorADMX(def definition, n names) string {
	gp := def.GroupPolicy
	var b strings.Builder
	b.WriteString(header)
	fmt.Fprintf(&b, "<policyDefinitions xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" revision=%q schemaVersion=%q xmlns=%q>\n", gp.Revision, schemaVersion, gpNamespace)
	b.WriteString("  <policyNamespaces>\n")
	fmt.Fprintf(&b, "    <target prefix=%q namespace=%q />\n", n.vendorPrefix, n.vendorNS)
	b.WriteString("  </policyNamespaces>\n")
	fmt.Fprintf(&b, "  <resources minRequiredRevision=%q />\n", gp.Revision)
	b.WriteString("  <categories>\n")
	fmt.Fprintf(&b, "    <category name=%q displayName=\"$(string.%s)\" />\n", gp.VendorCategory, gp.VendorCategory)
	b.WriteString("  </categories>\n")
	b.WriteString("</policyDefinitions>\n")
	return b.String()
}

func productADMX(def definition, n names) string {
	gp := def.GroupPolicy
	key := def.WindowsPolicyKey
	var b strings.Builder
	b.WriteString(header)
	fmt.Fprintf(&b, "<policyDefinitions xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" revision=%q schemaVersion=%q xmlns=%q>\n", gp.Revision, schemaVersion, gpNamespace)
	b.WriteString("  <policyNamespaces>\n")
	fmt.Fprintf(&b, "    <target prefix=%q namespace=%q />\n", n.productPrefix, n.productNS)
	fmt.Fprintf(&b, "    <using prefix=%q namespace=%q />\n", n.vendorPrefix, n.vendorNS)
	b.WriteString("  </policyNamespaces>\n")
	fmt.Fprintf(&b, "  <resources minRequiredRevision=%q />\n", gp.Revision)
	b.WriteString("  <supportedOn>\n    <definitions>\n")
	fmt.Fprintf(&b, "      <definition name=%q displayName=\"$(string.%s)\" />\n", n.supportedOn, n.supportedOn)
	b.WriteString("    </definitions>\n  </supportedOn>\n")
	b.WriteString("  <categories>\n")
	fmt.Fprintf(&b, "    <category name=%q displayName=\"$(string.%s)\" explainText=\"$(string.%s_Explain)\">\n", gp.ProductCategory, gp.ProductCategory, gp.ProductCategory)
	fmt.Fprintf(&b, "      <parentCategory ref=\"%s:%s\" />\n", n.vendorPrefix, gp.VendorCategory)
	b.WriteString("    </category>\n  </categories>\n")
	b.WriteString("  <policies>\n")
	for _, p := range def.Policies {
		// `class="Both"`: Cmdr reads the policy key under HKLM and HKCU, so an admin can set each
		// policy for the computer or for one user (the machine's value wins per name).
		attrs := fmt.Sprintf("name=%q class=\"Both\" displayName=\"$(string.%s)\" explainText=\"$(string.%s_Explain)\"", p.Name, p.Name, p.Name)
		if p.Kind != kindBool {
			attrs += fmt.Sprintf(" presentation=\"$(presentation.%s)\"", p.Name)
		}
		attrs += " key=" + attr(key)
		if p.Kind == kindBool {
			attrs += fmt.Sprintf(" valueName=%q", p.Name)
		}
		fmt.Fprintf(&b, "    <policy %s>\n", attrs)
		fmt.Fprintf(&b, "      <parentCategory ref=%q />\n", gp.ProductCategory)
		fmt.Fprintf(&b, "      <supportedOn ref=%q />\n", n.supportedOn)
		switch p.Kind {
		case kindBool:
			// A REG_DWORD: 1 restricts, 0 is "not managed" (`registry_values.rs`).
			b.WriteString("      <enabledValue>\n        <decimal value=\"1\" />\n      </enabledValue>\n")
			b.WriteString("      <disabledValue>\n        <decimal value=\"0\" />\n      </disabledValue>\n")
		case kindString:
			// A REG_SZ under the policy key; disabling the policy deletes it.
			fmt.Fprintf(&b, "      <elements>\n        <text id=%q valueName=%q required=\"true\" />\n      </elements>\n", p.Name, p.Name)
		case kindStringList:
			// REG_SZ values named 1, 2, … in a subkey named after the policy (`valuePrefix=""`),
			// which the app reads as the list.
			fmt.Fprintf(&b, "      <elements>\n        <list id=%q key=%s valuePrefix=\"\" />\n      </elements>\n", p.Name, attr(key+`\`+p.Name))
		}
		b.WriteString("    </policy>\n")
	}
	b.WriteString("  </policies>\n")
	b.WriteString("</policyDefinitions>\n")
	return b.String()
}

func productADML(def definition, n names) string {
	gp := def.GroupPolicy
	strs := [][2]string{
		{gp.ProductCategory, gp.ProductCategory},
		{gp.ProductCategory + "_Explain", gp.ProductExplain},
		{n.supportedOn, gp.SupportedOn},
	}
	var presentations []string
	for _, p := range def.Policies {
		strs = append(strs, [2]string{p.Name, p.DisplayName}, [2]string{p.Name + "_Explain", p.Explain + "\n\n" + registryNote(def.WindowsPolicyKey, p)})
		switch p.Kind {
		case kindString:
			presentations = append(presentations, fmt.Sprintf("      <presentation id=%q>\n        <textBox refId=%q>\n          <label>%s</label>\n        </textBox>\n      </presentation>\n", p.Name, p.Name, text(p.Label)))
		case kindStringList:
			presentations = append(presentations, fmt.Sprintf("      <presentation id=%q>\n        <listBox refId=%q>%s</listBox>\n      </presentation>\n", p.Name, p.Name, text(p.Label)))
		}
	}
	return adml(gp.Revision, gp.ProductCategory, "Group Policy settings for "+gp.ProductCategory+".", strs, presentations)
}

// registryNote ends each explain text with what the policy writes, for admins who set the registry
// another way (a script, an RMM tool) or check a PC with `reg query`.
func registryNote(key string, p policy) string {
	switch p.Kind {
	case kindBool:
		return fmt.Sprintf("Registry: %s, value %s (REG_DWORD), 1 when enabled and 0 when disabled.", key, p.Name)
	case kindString:
		return fmt.Sprintf("Registry: %s, value %s (REG_SZ).", key, p.Name)
	default:
		return fmt.Sprintf("Registry: %s\\%s, one REG_SZ value per entry, named 1, 2, and so on.", key, p.Name)
	}
}

func adml(rev, displayName, description string, strs [][2]string, presentations []string) string {
	var b strings.Builder
	b.WriteString(header)
	fmt.Fprintf(&b, "<policyDefinitionResources xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" revision=%q schemaVersion=%q xmlns=%q>\n", rev, schemaVersion, gpNamespace)
	fmt.Fprintf(&b, "  <displayName>%s</displayName>\n", text(displayName))
	fmt.Fprintf(&b, "  <description>%s</description>\n", text(description))
	b.WriteString("  <resources>\n    <stringTable>\n")
	for _, s := range strs {
		fmt.Fprintf(&b, "      <string id=%q>%s</string>\n", s[0], text(s[1]))
	}
	b.WriteString("    </stringTable>\n")
	if len(presentations) > 0 {
		b.WriteString("    <presentationTable>\n")
		for _, p := range presentations {
			b.WriteString(p)
		}
		b.WriteString("    </presentationTable>\n")
	}
	b.WriteString("  </resources>\n</policyDefinitionResources>\n")
	return b.String()
}

// text escapes element content, keeping newlines as they are: the Group Policy editor shows an
// explain text's line breaks.
func text(s string) string {
	return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;").Replace(s)
}

// attr is a double-quoted attribute value. Registry paths hold backslashes, which `%q` would double.
func attr(s string) string {
	return `"` + strings.NewReplacer("&", "&amp;", "<", "&lt;", `"`, "&quot;").Replace(s) + `"`
}

var (
	stringRef       = regexp.MustCompile(`\$\(string\.([^)]+)\)`)
	presentationRef = regexp.MustCompile(`\$\(presentation\.([^)]+)\)`)
	stringID        = regexp.MustCompile(`<string id="([^"]+)">`)
	presentationID  = regexp.MustCompile(`<presentation id="([^"]+)">`)
	refID           = regexp.MustCompile(`refId="([^"]+)"`)
	elementID       = regexp.MustCompile(`<(?:text|list) id="([^"]+)"`)
)

// checkReferences holds an ADMX and its ADML together the way the Group Policy editor does when
// it loads them: every `$(string.X)` and `$(presentation.X)` resolves, no string goes unused, and
// every presentation control names an element of the ADMX.
func checkReferences(admx, admlFile file) error {
	a, l := string(admx.content), string(admlFile.content)
	var problems []string
	ids := set(stringID, l)
	used := set(stringRef, a)
	for id := range used {
		if !ids[id] {
			problems = append(problems, fmt.Sprintf("%s names $(string.%s), which %s doesn't define", admx.path, id, admlFile.path))
		}
	}
	for id := range ids {
		if !used[id] {
			problems = append(problems, fmt.Sprintf("%s defines the string %s, which %s never uses", admlFile.path, id, admx.path))
		}
	}
	presIDs := set(presentationID, l)
	for id := range set(presentationRef, a) {
		if !presIDs[id] {
			problems = append(problems, fmt.Sprintf("%s names $(presentation.%s), which %s doesn't define", admx.path, id, admlFile.path))
		}
	}
	elements := set(elementID, a)
	for id := range set(refID, l) {
		if !elements[id] {
			problems = append(problems, fmt.Sprintf("%s has a control for %s, which isn't an element in %s", admlFile.path, id, admx.path))
		}
	}
	if len(problems) > 0 {
		sort.Strings(problems)
		return fmt.Errorf("the generated template doesn't hold together:\n  %s", strings.Join(problems, "\n  "))
	}
	return nil
}

func set(re *regexp.Regexp, s string) map[string]bool {
	out := map[string]bool{}
	for _, m := range re.FindAllStringSubmatch(s, -1) {
		out[m[1]] = true
	}
	return out
}
